fn render_quiz_page(state: &AppState, quiz: &Quiz) -> String {
    let title = escape_html(&quiz.title);
    let total = quiz.questions.len();
    let active_total = quiz.questions.iter().filter(|question| question.active).count();
    let mut content = format!(
        "<div class=\"breadcrumbs\"><a href=\"/moderate\">← All quizzes</a></div><div class=\"page-head\"><div><h1>{title}</h1><div class=\"meta mt-2\">{active_total} of {total} questions active · <a href=\"/moderate/quizzes/{}/settings\">Settings</a></div></div><div class=\"buttons\"><a class=\"btn btn--ghost\" href=\"/moderate/quizzes/{}/preview\">Preview</a></div></div>",
        quiz.id, quiz.id
    );
    content.push_str(&format!(
        "<section class=\"section mt-0\"><div class=\"section-head\"><h2>Questions</h2><a class=\"btn\" href=\"/moderate/quizzes/{}/questions/new\">Add question</a></div>",
        quiz.id
    ));
    if quiz.questions.is_empty() {
        content.push_str("<div class=\"empty\">No questions yet. Add a question to build this quiz.</div>");
    } else {
        content.push_str("<ol class=\"question-list\">");
        let mut active_number = 0;
        for (index, question) in quiz.questions.iter().enumerate() {
            if question.active {
                active_number += 1;
            }
            content.push_str(&render_question_item(state, quiz, question, index, active_number));
        }
        content.push_str("</ol>");
    }
    content.push_str("</section>");
    page(&quiz.title, &content)
}

fn render_question_item(
    state: &AppState,
    quiz: &Quiz,
    question: &Question,
    index: usize,
    active_number: usize,
) -> String {
    let body = escape_html(&question.body);
    let inactive_class = if question.active {
        ""
    } else {
        " question-item--inactive"
    };
    let displayed_number = if question.active {
        active_number.to_string()
    } else {
        "—".to_owned()
    };
    let mut item = format!(
        "<li class=\"card question-item{inactive_class}\" id=\"question-{}\"><div class=\"question-item__num\">{displayed_number}</div><div><div class=\"question-item__body\">{body}</div><ul class=\"question-item__options\">",
        question.id
    );
    for (option_index, option) in question.options.iter().enumerate() {
        let correct = if option.correct { " class=\"is-correct\"" } else { "" };
        item.push_str(&format!(
            "<li{correct}>{}. {}</li>",
            option_letter(option_index),
            escape_html(&option.body)
        ));
    }
    item.push_str("</ul></div><div class=\"question-item__actions\"><div class=\"buttons\">");
    let move_path = format!(
        "/moderate/quizzes/{}/questions/{}/move",
        quiz.id, question.id
    );
    item.push_str(&move_button(
        &move_path,
        &state.csrf_token,
        "up",
        "↑",
        "Move up",
        index == 0,
    ));
    item.push_str(&move_button(
        &move_path,
        &state.csrf_token,
        "down",
        "↓",
        "Move down",
        index + 1 == quiz.questions.len(),
    ));
    item.push_str("</div>");
    item.push_str(&format!(
        "<form class=\"active-toggle\" method=\"post\" action=\"/moderate/quizzes/{}/questions/{}/active\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><label class=\"checkbox\"><input type=\"checkbox\" name=\"active\" value=\"true\" onchange=\"this.form.submit()\"{}>Active</label></form>",
        quiz.id,
        question.id,
        escape_html(&state.csrf_token),
        if question.active { " checked" } else { "" }
    ));
    item.push_str(&format!(
        "<div class=\"buttons\"><a class=\"btn btn--sm\" href=\"/moderate/quizzes/{}/questions/{}/edit\">Edit</a><form method=\"post\" action=\"/moderate/quizzes/{}/questions/{}/delete\" onsubmit=\"return confirm('Delete question?');\"><input type=\"hidden\" name=\"csrf\" value=\"{}\"><button class=\"btn btn--sm btn--danger\" type=\"submit\">Delete</button></form></div></div></li>",
        quiz.id,
        question.id,
        quiz.id,
        question.id,
        escape_html(&state.csrf_token)
    ));
    item
